#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

cd "$(git rev-parse --show-toplevel)"
BRANCH="integration/beta-polish-20261109-v2"
REPO_URL="https://github.com/denis-petruk/MuscleCuties"
RECORD_DIR="docs/release-audit/2026-11-09"
HEAD_SHA="$(git rev-parse --short=7 HEAD)"
TODAY="$(date +%Y-%m-%d)"

banner "MuscleCuties beta release — owner steps"

# ── 1. Pull request ───────────────────────────────────────────────────────
stage "Pull request"
say "The branch is pushed; the PR itself needs your GitHub session."
note "Branch $BRANCH at $HEAD_SHA. Compare against main."
open_url "$REPO_URL/compare/main...$BRANCH?expand=1"
step "Title it for the beta: \"Beta polish: onboarding, session and Today fixes\"."
step "Paste the release notes from docs/beta-readiness/RELEASE_READINESS.md."
step "Create the pull request and copy its number."
ask PR_NUMBER "PR number:"
if [[ ! "$PR_NUMBER" =~ ^[0-9]+$ ]]; then
  warn "That isn't a PR number; re-run this wizard with the number GitHub showed you."
  exit 1
fi
say "PR #$PR_NUMBER recorded for this run."

# ── 2. CI ─────────────────────────────────────────────────────────────────
stage "CI on the branch"
say "CI runs automatically for every push to integration/**, so the push already started it."
note "Commit under test: $HEAD_SHA on $BRANCH."
open_url "$REPO_URL/actions?query=branch%3A$BRANCH"
open_url "$REPO_URL/commit/$HEAD_SHA"
step "Open the newest CI run for this branch and confirm it says completed successfully."
step "Green means all of these are green: verify_source, verify_plan_generation,"
step "verify_ios_compile (on xcode-27), postgres_verify / verify_postgres_compatibility,"
step "and the aggregate required job."
step "The commit page's checks summary must read 0 failing and 0 pending."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  step "Or watch from here:"
  note "  gh run list --branch $BRANCH --limit 1"
  note "  gh run watch <run-id>"
else
  note "gh is not signed in; the public run page above is enough."
fi
if ! confirm "Is the run on $HEAD_SHA completed successfully with every required job green?"; then
  warn "Stop here: red or pending is a NO-GO. Fix it, push, and re-run this wizard."
  exit 1
fi

# ── 3. Mac simulator acceptance ───────────────────────────────────────────
stage "Simulator acceptance (Mac only)"
say "This workspace can't build iOS; the build and the eyes have to be yours."
step "Run the simulator-target build (needs Xcode and the MAUI workload):"
note "  dotnet build src/MuscleCuties.UI/MuscleCuties.UI.csproj -c Debug \\"
note "    -f net10.0-ios -p:RuntimeIdentifier=iossimulator-arm64"
if confirm "Run that build now on this machine?"; then
  dotnet build src/MuscleCuties.UI/MuscleCuties.UI.csproj -c Debug \
    -f net10.0-ios -p:RuntimeIdentifier=iossimulator-arm64 \
    2>&1 | tee /tmp/mc-beta-ios-build.log
  note "Build log: /tmp/mc-beta-ios-build.log"
fi
step "Install the .app on a booted simulator and launch it (or press Run in Rider/VS)."
note "  xcrun simctl install booted src/MuscleCuties.UI/bin/Debug/net10.0-ios/iossimulator-arm64/MuscleCuties.UI.app"
pause "Launch the app on the simulator, then press Enter to walk the checks."

mkdir -p "$RECORD_DIR"
QA_RECORD="$RECORD_DIR/OWNER_SIMULATOR_QA_${TODAY}.md"
{
  printf '# Owner simulator check — %s\n\n' "$TODAY"
  printf -- '- Branch: `%s` at `%s`\n' "$BRANCH" "$HEAD_SHA"
  printf -- '- Build: `net10.0-ios`, Debug, `iossimulator-arm64`\n'
  printf -- '- Device / iOS / appearance / language: (fill in)\n\n'
  printf '| ID | Check | Result |\n| --- | --- | --- |\n'
} > "$QA_RECORD"

QA_FAILED=0
qa() {
  local id="$1" question="$2" result="FAIL"
  if confirm "$question"; then result="PASS"; else QA_FAILED=1; fi
  printf '| %s | %s | %s |\n' "$id" "$question" "$result" >> "$QA_RECORD"
}

say "Walk these on the smallest iPhone you support and on iPhone 17 Pro,"
say "light and dark, English and Russian:"
qa "E-04" "Invalid onboarding form shows the reason right above Continue?"
qa "E-06" "A beginner general-strength day no longer says Heavy?"
qa "E-07" "Opening a session shows no no-activities flash?"
qa "E-05" "Today's phase header matches the phase the quiz/Train tab shows?"
qa "J04" "Journey 4 (injury restrictions) still passes?"
qa "J06" "Journey 6 (preview and apply) still passes?"
qa "J07" "Journey 7 (schedule and reschedule) still passes?"
qa "J08" "Journey 8 (session logging) still passes?"
qa "J09" "Journey 9 (history) still passes?"
qa "J10" "Journey 10 (cycle) still passes?"
qa "J11" "Journey 11 (nutrition) still passes?"
qa "J12" "Journey 12 (measurements) still passes?"
qa "J13" "Journey 13 (offline and retry) still passes?"
qa "J14" "Journey 14 (RU at large text) still passes?"
qa "J15" "Journey 15 (first-run install) still passes?"

step "Add one screenshot per defect and one home-screen capture, then fill in"
say "device, iOS version, appearance and language at the top of:"
note "  $QA_RECORD"
note "Then replace the G12 Simulator row in docs/beta-readiness/RELEASE_READINESS.md with these results."
pause "Press Enter once the record is filled in."

if (( QA_FAILED )); then
  warn "At least one check failed. That is a NO-GO: fix, push, and repeat this stage."
fi

# ── 4. AWS alarm subscription ─────────────────────────────────────────────
stage "Operational alarms reach a human"
say "observability.yaml now creates the SNS email subscription its alarms need."
warn "This is a live CloudFormation change. Only continue if you authorize it now."
open_url "https://console.aws.amazon.com/cloudformation/home#/stacks"
step "Open the MuscleCuties observability stack for the beta account."
step "Choose Update stack → Replace current template → Upload"
note "  infra/cloudformation/observability.yaml"
step "Create the change set and confirm it only adds the SNS subscription"
step "named AlarmEmailSubscription (no replacement of the topic or alarms)."
step "Execute the change set, then open the confirmation email AWS sends to"
step "the NotificationEmail address and click Confirm subscription."
if confirm "Did the change set execute and the subscription get confirmed?"; then
  step "Verify from the CLI (read-only):"
  note "  aws sns list-subscriptions-by-topic --topic-arn <AlarmTopicArn>"
  ask ALARM_TOPIC_ARN "Topic ARN (blank to skip the check):"
  if [[ -n "${ALARM_TOPIC_ARN:-}" ]]; then
    aws sns list-subscriptions-by-topic --topic-arn "$ALARM_TOPIC_ARN" \
      --query 'Subscriptions[].{Protocol:Protocol,Endpoint:Endpoint,Arn:SubscriptionArn}' \
      --output table || warn "The CLI call failed; check your AWS profile and region."
  fi
else
  warn "Alarms stay silent until this is done; record it as an open A11 item."
fi

# ── 5. Product decisions ──────────────────────────────────────────────────
stage "The four policy decisions"
say "These block the remaining audit items. The research and reasoning are in"
note "  docs/release-audit/2026-11-09/WORKOUT_POLICY_RESEARCH.md"
say ""
step "S-03  A) keep set-only readiness adjustment (recommended)  B) add load step-down"
ask S03_CHOICE "S-03 choice [A/B]:"
step "Policy 5  A) amend to symptoms/readiness only (recommended)  B) keep cycle-phase dosing"
ask POLICY5_CHOICE "Policy 5 choice [A/B]:"
step "S-04  A) inline \"This hurts\" action in a session (recommended)  B) keep end-session-only"
ask S04_CHOICE "S-04 choice [A/B]:"
step "S-05  A) delete the unpublished seven-day window (recommended)  B) keep it, with a rationale"
ask S05_CHOICE "S-05 choice [A/B]:"

DECISIONS="$RECORD_DIR/OWNER_DECISIONS_${TODAY}.md"
{
  printf '# Owner policy decisions — %s\n\n' "$TODAY"
  printf -- '- Branch: `%s` at `%s`\n' "$BRANCH" "$HEAD_SHA"
  printf -- '- PR: #%s\n\n' "$PR_NUMBER"
  printf '| Item | Decision |\n| --- | --- |\n'
  printf '| S-03 load step | %s |\n' "$S03_CHOICE"
  printf '| Policy 5 cycle dose | %s |\n' "$POLICY5_CHOICE"
  printf '| S-04 pain surface | %s |\n' "$S04_CHOICE"
  printf '| S-05 seven-day window | %s |\n' "$S05_CHOICE"
} > "$DECISIONS"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$DECISIONS"
note "Implementing the answers is a separate coding change; commit this record with it."

finish
warn "Reminder: this wizard never merges, deploys the app, or writes Beta data."
